-- examples/billing.ts: canCreateTodo()
CREATE OR REPLACE FUNCTION app.can_create_todo(
  sub app.subscription,
  count integer
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  "limit" integer;
BEGIN
  "limit" := app.todo_limit((sub).plan);
  RETURN count < "limit";
END;
$$;

-- examples/pricing.ts: isNotEmpty()
CREATE OR REPLACE FUNCTION app.is_not_empty(
  coupon_code text
)
RETURNS boolean
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  IF coupon_code IS NULL THEN
    RETURN false;
  END IF;
  RETURN coupon_code IS DISTINCT FROM '';
END;
$$;

-- examples/pricing.ts: priceCents()
CREATE OR REPLACE FUNCTION app.price_cents(
  list_cents integer,
  percent_off double precision
)
RETURNS double precision
LANGUAGE plpgsql
IMMUTABLE
AS $$
DECLARE
  discount double precision;
BEGIN
  discount := COALESCE(percent_off, 0);
  RETURN list_cents * (100 - discount) / 100;
END;
$$;

-- examples/billing.ts: seatLimit()
CREATE OR REPLACE FUNCTION app.seat_limit(
  tier app.tier,
  extra_seats integer
)
RETURNS integer
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  RETURN CASE tier
    WHEN 'free' THEN 1
    WHEN 'starter' THEN 1
    WHEN 'pro' THEN 10 + extra_seats
    ELSE 100 + extra_seats * 2
  END;
END;
$$;

-- examples/billing.ts: todoLimit()
CREATE OR REPLACE FUNCTION app.todo_limit(
  plan app.plan
)
RETURNS integer
LANGUAGE plpgsql
IMMUTABLE
AS $$
BEGIN
  IF plan = 'free' THEN
    RETURN 3;
  ELSIF plan = 'pro' THEN
    RETURN 100;
  END IF;
  RETURN 1000;
END;
$$;
